mapper.select:
${pagingTop}
SELECT
	A.lecture_idx, B.lecture_apply_idx, B.applicant_name, B.applicant_sex, B.applicant_age,
	B.applicant_phone, B.applicant_belong, B.reception_status, B.add_id, B.add_date
FROM
	RELAY_LECTURE A, RELAY_LECTURE_APPLY B
WHERE
	A.lecture_idx = B.lecture_idx
AND	B.lecture_idx = #{lecture_idx}


AND	${search_type} LIKE '%'||#{search_text}||'%'


AND	reception_status = #{reception_status}

ORDER BY B.lecture_apply_idx DESC
${pagingBottom}

SELECT COUNT(*) FROM RELAY_LECTURE A, RELAY_LECTURE_APPLY B WHERE A.lecture_idx = B.lecture_idx AND B.lecture_idx = #{lecture_idx}
AND ${search_type} LIKE '%'||#{search_text}||'%'
AND reception_status = #{reception_status}

mapper.update:
UPDATE
	RELAY_LECTURE_APPLY
SET
	reception_status = #{reception_status}
WHERE
	lecture_idx = #{lecture_idx}
AND	lecture_apply_idx = #{lecture_apply_idx}
